import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Vehicle-acquisition source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/23-vehicle-acquisition-profile.md","filePath":"reference/23-vehicle-acquisition-profile.md","lastUpdated":1788530310000}'),o={name:"reference/23-vehicle-acquisition-profile.md"};function s(c,e,n,h,l,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="vehicle-acquisition-source-profile" tabindex="-1">Vehicle-acquisition source profile <a class="header-anchor" href="#vehicle-acquisition-source-profile" aria-label="Permalink to &quot;Vehicle-acquisition source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The vehicle-purchase profile uses B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter IV, “Influence of Nakshatras,” movable-Nakshatra classification, printed page 10 (PDF page 14):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. The cited passage says that Shravana, Dhanishtha, Shatabhisha, Punarvasu and Swati are auspicious for acquiring vehicles. It does not provide a complete vehicle-purchase election in that passage.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Five movable Nakshatras are auspicious for acquiring vehicles</td><td><code>prefer_nakshatras</code></td><td>These stars receive a disclosed +1 activity-specific preference. The passage does not state that every other star must be rejected.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>The existing Labh-Choghadiya, Bhadra-Tithi, Friday and fixed-Lagna preferences are transparent project-ranking rules. They are not supported by this Chapter IV locator and do not inherit its verified status. The claim therefore verifies the activity-specific Nakshatra preference—not a universal or complete vehicle election. MCP returns <code>muhurta.vehicle.acquisition</code>; the browser consumes the same generated preference list.</p>',9)])])}const f=a(o,[["render",s]]);export{u as __pageData,f as default};
